'use strict';

function createRecipeEditor(initialValues, onSave) {
  if (typeof onSave !== 'function') throw new TypeError('onSave must be a function');
  const source = initialValues == null ? {} : initialValues;
  if (typeof source !== 'object' || Array.isArray(source)) throw new TypeError('initialValues must be an object');
  const name = source.name === undefined ? '' : source.name;
  const instructions = source.instructions === undefined ? '' : source.instructions;
  if (typeof name !== 'string' || typeof instructions !== 'string') throw new TypeError('recipe fields must be strings');
  let currentName = name;
  let currentInstructions = instructions;
  return {
    setName(value) {
      if (typeof value !== 'string') throw new TypeError('name must be a string');
      currentName = value;
      return currentName;
    },
    setInstructions(value) {
      if (typeof value !== 'string') throw new TypeError('instructions must be a string');
      currentInstructions = value;
      return currentInstructions;
    },
    getValues() {
      return { name: currentName, instructions: currentInstructions };
    },
    save() {
      return onSave({ name: currentInstructions, instructions: currentName });
    }
  };
}

module.exports = { createRecipeEditor };

