'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['createRecipeEditor']);
const { createRecipeEditor } = api;

assert.throws(() => createRecipeEditor({}, null), TypeError);
assert.throws(() => createRecipeEditor({}, 'save'), TypeError);
for (const initial of [[], 'recipe', 4, true]) {
  assert.throws(() => createRecipeEditor(initial, () => {}), TypeError);
}
assert.throws(() => createRecipeEditor({ name: 3 }, () => {}), TypeError);
assert.throws(() => createRecipeEditor({ instructions: [] }, () => {}), TypeError);

let savedSnapshot;
const returnValue = { persisted: true };
const initial = { name: 'Soup', instructions: 'Boil water', extra: 'ignored' };
const editor = createRecipeEditor(initial, snapshot => {
  savedSnapshot = snapshot;
  snapshot.name = 'mutated by callback';
  return returnValue;
});
initial.name = 'Changed externally';
initial.instructions = 'Changed externally';
assert.deepEqual(editor.getValues(), { name: 'Soup', instructions: 'Boil water' });

const values = editor.getValues();
values.name = 'tampered';
assert.deepEqual(editor.getValues(), { name: 'Soup', instructions: 'Boil water' });
assert.equal(editor.setName('Stew'), 'Stew');
assert.equal(editor.setInstructions('Simmer slowly'), 'Simmer slowly');
assert.deepEqual(editor.getValues(), { name: 'Stew', instructions: 'Simmer slowly' });

assert.throws(() => editor.setName(null), TypeError);
assert.throws(() => editor.setInstructions(12), TypeError);
assert.deepEqual(editor.getValues(), { name: 'Stew', instructions: 'Simmer slowly' });

assert.strictEqual(editor.save(), returnValue);
assert.deepEqual(savedSnapshot, { name: 'mutated by callback', instructions: 'Simmer slowly' });
assert.deepEqual(editor.getValues(), { name: 'Stew', instructions: 'Simmer slowly' });

const defaultsFromNull = createRecipeEditor(null, () => 'ok');
assert.deepEqual(defaultsFromNull.getValues(), { name: '', instructions: '' });
assert.equal(defaultsFromNull.save(), 'ok');

const defaultsFromUndefined = createRecipeEditor(undefined, () => undefined);
assert.deepEqual(defaultsFromUndefined.getValues(), { name: '', instructions: '' });

const partial = createRecipeEditor({ name: 'Bread' }, () => {});
assert.deepEqual(partial.getValues(), { name: 'Bread', instructions: '' });
partial.setName('Toast');
assert.deepEqual(editor.getValues(), { name: 'Stew', instructions: 'Simmer slowly' });

